entry.source:
ontokin "0.2";
module Transitive @ "transitive";
profile "construction-0.1";

import shapes @ "shapes-import" from "example.geometry" version "1.0.0" digest "sha256:f684a724c77210c07208dd0986ed460ed41f8aa502ccc2cd82a6ad549cab63cb";

fn radius @ "entry-radius"(value: Length) -> Length {
    return 99 * value;
}
scene Demo @ "demo" {
    duration = 1[s];
    gravity = vector(world, 0[m/s^2], 0[m/s^2], 0[m/s^2]);
    object ball @ "ball": shapes.Ball {
        base = 0.2[m];
    }
}

modules.source:
ontokin "0.2";
module GeometryLibrary @ "geometry";
profile "construction-0.1";

import arithmetic @ "arithmetic-import" from "example.arithmetic" version "1.0.0" digest "sha256:0324f021efeba5a20e2a0bf05e920336f2b9307497705eb85d8d575f5a5e8081";

private fn radius @ "radius"(value: Length) -> Length {
    return arithmetic.twice(value);
}
public class Ball @ "ball" {
    public param base @ "base": Length = 0.1[m];
    geometry = sphere(radius(self.base));
    appearance = rgba(0.3, 0.8, 0.4, 1);
}

ontokin "0.2";
module Arithmetic @ "arithmetic";
profile "construction-0.1";

public fn twice @ "twice"(value: Length) -> Length {
    return 2 * value;
}
